window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dedd2303dc37234b"]={"versions": [{"id": "FIG-dedd2303dc37234b", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur-Blockschaltbild zur Verortung des Diagnostic Log and Trace (Dlt) Moduls innerhalb einer AUTOSAR-Systemarchitektur. Das Diagramm zeigt die Schichtenstruktur zwischen Applikationsebene, Middleware und Kommunikationsbussen sowie den Nachrichtenfluss für Logging- und Tracing-Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application</strong>: Drei separate Applikationsblöcke oberhalb der Middleware. Zwei davon senden explizit Datenströme an das Dlt-Modul; eine Applikation ist als zusätzliche Entität ohne direkte Pfeilverbindung dargestellt.</li>\n<li><strong>Middleware</strong>: Umfassender Architekturblock, der interne Systemmodule kapselt.</li>\n<li><strong>Dlt module</strong>: Gelb hervorgehobene Kernkomponente innerhalb der Middleware. Beinhaltet bzw. steuert ein nachgeschaltetes Filter-Element (<code>filter</code>), symbolisiert durch ein Trichtersymbol am Ausgang.</li>\n<li><strong>SW module</strong>: Ein weiteres Softwaremodul (grau hinterlegt) innerhalb der Middleware mit gerichteter Verbindung zum Dlt-Modul.</li>\n<li><strong>Communications Bus</strong>: Zwei Kommunikationsbus-Instanzen unterhalb der Middleware, die als Ausgabekanäle für gefilterte Dlt-Nachrichten dienen.</li>\n<li><strong>Schnittstellen / Datenflüsse</strong>:</li>\n<li><code>Logging Information</code>: Gerichtete Pfeile von zwei <code>Application</code>-Instanzen zum <code>Dlt module</code>.</li>\n<li>Gerichteter Pfeil von <code>SW module</code> zum <code>Dlt module</code>.</li>\n<li>Gefilterte Ausgabepfeile vom Trichter (<code>filter</code>) des <code>Dlt module</code> auf die beiden <code>Communications Bus</code>-Instanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Mehrere Quellen (Applikationen oberhalb der Middleware sowie interne Software-Module innerhalb der Middleware) erzeugen zur Laufzeit Protokoll- und Tracing-Nachrichten (<code>Logging Information</code>).</li>\n<li>Die Logging-Daten werden an das zentrale <code>Dlt module</code> übergeben.</li>\n<li>Innerhalb oder am Ausgang des <code>Dlt module</code> erfolgt eine Filterung (<code>filter</code>) der eingehenden Nachrichtenströme.</li>\n<li>Die gefilterten Datenströme werden über Schnittstellen parallel oder selektiv auf mehrere Kommunikationsbusse (<code>Communications Bus</code>) zur externen Übertragung bzw. Aufzeichnung ausgeleitet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die funktionale Kapselung und zentrale Sammelfunktion des Dlt-Moduls für diagnose- und entwicklungsrelevante Log-Daten aus unterschiedlichen Architektur-Schichten. Für Entwickler impliziert dies, dass Applikationen und Middleware-Softwaremodule nicht direkt auf den Kommunikationsbus schreiben, sondern standardisierte Schnittstellen zum Dlt-Modul nutzen müssen. Die Filter-Komponente bestimmt dabei maßgeblich, welche Log- und Trace-Meldungen unter Berücksichtigung von Bandbreitenbegrenzungen tatsächlich auf die Zielbusse weitergeleitet werden.</p>"}, {"id": "FIG-051db042f00ae0f8", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur-Blockschaltbild zur Verortung des Diagnostic Log and Trace (Dlt) Moduls innerhalb einer AUTOSAR-Systemarchitektur. Das Diagramm zeigt die Schichtenstruktur zwischen Applikationsebene, Middleware und Kommunikationsbussen sowie den Nachrichtenfluss für Logging- und Tracing-Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application</strong>: Drei separate Applikationsblöcke oberhalb der Middleware. Zwei davon senden explizit Datenströme an das Dlt-Modul; eine Applikation ist als zusätzliche Entität ohne direkte Pfeilverbindung dargestellt.</li>\n<li><strong>Middleware</strong>: Umfassender Architekturblock, der interne Systemmodule kapselt.</li>\n<li><strong>Dlt module</strong>: Gelb hervorgehobene Kernkomponente innerhalb der Middleware. Beinhaltet bzw. steuert ein nachgeschaltetes Filter-Element (<code>filter</code>), symbolisiert durch ein Trichtersymbol am Ausgang.</li>\n<li><strong>SW module</strong>: Ein weiteres Softwaremodul (grau hinterlegt) innerhalb der Middleware mit gerichteter Verbindung zum Dlt-Modul.</li>\n<li><strong>Communications Bus</strong>: Zwei Kommunikationsbus-Instanzen unterhalb der Middleware, die als Ausgabekanäle für gefilterte Dlt-Nachrichten dienen.</li>\n<li><strong>Schnittstellen / Datenflüsse</strong>:</li>\n<li><code>Logging Information</code>: Gerichtete Pfeile von zwei <code>Application</code>-Instanzen zum <code>Dlt module</code>.</li>\n<li>Gerichteter Pfeil von <code>SW module</code> zum <code>Dlt module</code>.</li>\n<li>Gefilterte Ausgabepfeile vom Trichter (<code>filter</code>) des <code>Dlt module</code> auf die beiden <code>Communications Bus</code>-Instanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Mehrere Quellen (Applikationen oberhalb der Middleware sowie interne Software-Module innerhalb der Middleware) erzeugen zur Laufzeit Protokoll- und Tracing-Nachrichten (<code>Logging Information</code>).</li>\n<li>Die Logging-Daten werden an das zentrale <code>Dlt module</code> übergeben.</li>\n<li>Innerhalb oder am Ausgang des <code>Dlt module</code> erfolgt eine Filterung (<code>filter</code>) der eingehenden Nachrichtenströme.</li>\n<li>Die gefilterten Datenströme werden über Schnittstellen parallel oder selektiv auf mehrere Kommunikationsbusse (<code>Communications Bus</code>) zur externen Übertragung bzw. Aufzeichnung ausgeleitet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die funktionale Kapselung und zentrale Sammelfunktion des Dlt-Moduls für diagnose- und entwicklungsrelevante Log-Daten aus unterschiedlichen Architektur-Schichten. Für Entwickler impliziert dies, dass Applikationen und Middleware-Softwaremodule nicht direkt auf den Kommunikationsbus schreiben, sondern standardisierte Schnittstellen zum Dlt-Modul nutzen müssen. Die Filter-Komponente bestimmt dabei maßgeblich, welche Log- und Trace-Meldungen unter Berücksichtigung von Bandbreitenbegrenzungen tatsächlich auf die Zielbusse weitergeleitet werden.</p>"}], "trans": [{"from": "FIG-dedd2303dc37234b", "to": "FIG-051db042f00ae0f8", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-051db042f00ae0f8", "to": "FIG-dedd2303dc37234b", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
